var count = 200;
var timeOffset = 2.5;
var posOffset = 2.5;

function setup() {
	createCanvas(820, 820);
}

function draw() {
	background(0);
	noFill();
	strokeWeight(0.8);
	//smooth();
	translate(width / 2 - 240, height / 2);

	for (var z = 0; z < 2; z++) {
		if (z == 1) {
			scale(1, -1);
		}

		for (var i = 0; i < count; i++) {
			var h = map(i, 0, count, 200, 300);
			var s = map(i, 0, count, 0, 360);
			var b = map(i, 0, count, 141, 360);
			var a = map(i, 0, count, 0, 255);

			stroke(250);
			var value = sin(radians(frameCount + i * timeOffset));
			var end = map(abs(value), 0, 1, PI, TWO_PI);
			var waveHeight = map(abs(value), 0, 1, 0, 350 * cos(radians(frameCount + i)));
			arc(i * posOffset, 0, 200, waveHeight, PI, end, PIE);
		}
	}
}
